const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two points in Norwegian Sea
  const point1 = ee.Geometry.Point([-58.944881, 50.282684]);
  const point2 = ee.Geometry.Point([-54.128047, 50.415337]);

  // Create a region around both points for filtering
  const region = ee.Geometry.BBox(-59.5, 50.0, -53.5, 50.8);

  // Date range - single day
  const startDate = '2019-09-01';
  const endDate = '2019-09-02';

  // Get Sentinel-2 surface reflectance collection
  const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  // Check if collection is empty
  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 images found: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the least cloudy image
  const image = s2Col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Calculate Normalized Difference Turbidity Index (NDTI)
  // NDTI = (Red - Green) / (Red + Green)
  // Higher values indicate more turbid/milky water
  const ndti = image.normalizedDifference(['B4', 'B3']).rename('NDTI');

  // Extract NDTI values at both points
  const val1 = ndti.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point1,
    scale: 100,
    maxPixels: 1e9
  }).get('NDTI');

  const val2 = ndti.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point2,
    scale: 100,
    maxPixels: 1e9
  }).get('NDTI');

  const ndti1 = val1.getInfo();
  const ndti2 = val2.getInfo();

  console.log(`Point 1 NDTI: ${ndti1 !== null ? ndti1.toFixed(4) : 'null'}`);
  console.log(`Point 2 NDTI: ${ndti2 !== null ? ndti2.toFixed(4) : 'null'}`);

  // Check for valid pixels
  if (ndti1 === null || ndti2 === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid values
  if (Math.abs(ndti1) > 1 || Math.abs(ndti2) > 1 || 
      isNaN(ndti1) || isNaN(ndti2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values - higher NDTI means more turbid/milky water
  if (ndti1 > ndti2) {
    console.log("Point 1 has higher turbidity");
    console.log("<answer>A</answer>");
  } else {
    console.log("Point 2 has higher turbidity or equal");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
